def solve():
    # a[n] will store a_{n+1}
    a = [0] * 101 
    a[0] = 0 # a_1 = 0

    # Store max index i for n >= 31
    maximizing_indices = {}

    # Calculate a_n for n=2 up to 100
    for n in range(2, 101):
        max_val = -1
        best_i = -1

        # i runs from 1 to n-1
        for i in range(1, n):
            # Recurrence: a_n = max_{1 <= i <= n - 1} {a_i + a_{n - i} + min(i, n - i)}
            # Indices used in calculation: a[i-1] and a[n-i-1]
            val = a[i-1] + a[n-i-1] + min(i, n - i)

            if val > max_val:
                max_val = val
                best_i = i

        a[n-1] = max_val

        if n >= 31:
            # We store i and n
            maximizing_indices[n] = best_i

    return a[100], maximizing_indices

result = solve()
print(f"a_100: {result[0]}")
print("Maximizing Indices (n=31 to 100):")
for n, i in result[1].items():
    print(f"n={n}: i={i}")
